(4187234, 601901, 67152, '<td valign="top">I like how the guy is looking out from behind the umbrella.  The colors from his sweater and umbrella really stand out against the grey background.</td>', 'I like how the guy is looking out from behind the umbrella.  The colors from his sweater and umbrella really stand out against the grey background.', '2007-10-22 12:37:27.000000', NULL, 1),
(4187268, 603083, 80096, '<td valign="top">Looks like a winner. ;-)</td>', 'Looks like a winner. ;-)', '2007-10-22 13:00:15.000000', NULL, 1),
