(4187277, 602100, 80096, '<td valign="top">Excellent.</td>', 'Excellent.', '2007-10-22 13:02:38.000000', NULL, 1),
(4187279, 602827, 41675, '<td valign="top">Aside from the pearl looking a bit funky to me with the yellow coloring, I like the background. Little bit of noise/grain in the shadow, but overall, good entry.</td>', 'Aside from the pearl looking a bit funky to me with the yellow coloring, I like the background. Little bit of noise/grain in the shadow, but overall, good entry.', '2007-10-22 13:03:16.000000', NULL, 1),
(4187281, 602541, 41675, '<td valign="top">Wow! Great sky. It looks surrealistic. I like the structure as well. A very dramatic image.</td>', 'Wow! Great sky. It looks surrealistic. I like the structure as well. A very dramatic image.', '2007-10-22 13:04:05.000000', NULL, 1),
(4187284, 603040, 41675, '<td valign="top">I always enjoy these types of photos. It''s simple, yet colorful. Basic background that doesn''t clutter up the image. Maybe a wee bit oversharpened to me, but overall it I like it.</td>', 'I always enjoy these types of photos. It''s simple, yet colorful. Basic background that doesn''t clutter up the image. Maybe a wee bit oversharpened to me, but overall it I like it.', '2007-10-22 13:05:01.000000', NULL, 1),
(4187289, 602987, 69368, '<td valign="top">I had the same idea and I tried and tried and tried... I did not enter! How did you do that?<br/>I like the sharpness of the drop, the enlargement of the leafs texture,the little reflected rainbow but also the colored light on the leaf it self! Might be a tad too dark.</td>', 'I had the same idea and I tried and tried and tried... I did not enter! How did you do that?I like the sharpness of the drop, the enlargement of the leafs texture,the little reflected rainbow but also the colored light on the leaf it self! Might be a tad too dark.', '2007-10-22 13:06:04.000000', NULL, 1),
(4187291, 602016, 69368, '<td valign="top">this is very intersting. looks like an old appatrementhouse or factory. Probably is some elektronic device.</td>', 'this is very intersting. looks like an old appatrementhouse or factory. Probably is some elektronic device.', '2007-10-22 13:08:22.000000', NULL, 1),
(4187294, 602820, 80096, '<td valign="top">Beautiful! 8</td>', 'Beautiful! 8', '2007-10-22 13:11:18.000000', NULL, 1),
(4187297, 603225, 66353, '<td valign="top">Great idea :)</td>', 'Great idea :)', '2007-10-22 13:11:45.000000', NULL, 1),
(4187298, 603225, 69368, '<td valign="top">this is a really funny idea. I like how the different persons have matching accessories.<br/>That leads me to the question: what does the "orange guy" do there???</td>', 'this is a really funny idea. I like how the different persons have matching accessories.That leads me to the question: what does the "orange guy" do there???', '2007-10-22 13:12:18.000000', NULL, 1),
(4187300, 602306, 80096, '<td valign="top">Spectacular! 10</td>', 'Spectacular! 10', '2007-10-22 13:13:00.000000', NULL, 1),
(4187308, 603075, 85097, '<td valign="top">Great capture of a real rainbow.  Its beautiful</td>', 'Great capture of a real rainbow.  Its beautiful', '2007-10-22 13:15:52.000000', NULL, 1),
(4187311, 602868, 85097, '<td valign="top">Nice colors, great DOF.  I think you did a great job with this.</td>', 'Nice colors, great DOF.  I think you did a great job with this.', '2007-10-22 13:17:20.000000', NULL, 1),
(4187312, 602306, 85097, '<td valign="top">Stunning!!</td>', 'Stunning!!', '2007-10-22 13:18:45.000000', NULL, 1),
(4187315, 603031, 85097, '<td valign="top">Double rainbow!</td>', 'Double rainbow!', '2007-10-22 13:20:52.000000', NULL, 1),
(4187316, 602006, 69368, '<td valign="top">this is beautiful! The reflected foliage actually reminds of a rainbow. A very serene scene!</td>', 'this is beautiful! The reflected foliage actually reminds of a rainbow. A very serene scene!', '2007-10-22 13:21:04.000000', NULL, 1),
(4187318, 601015, 85097, '<td valign="top">Very creative.</td>', 'Very creative.', '2007-10-22 13:21:36.000000', NULL, 1),
