(4188543, 602397, 41675, '<td valign="top">Intersting and kind of...spooky in a way. It''s the look in the eyes. Not crazy about the gold circle, but definitely imaginative.</td>', 'Intersting and kind of...spooky in a way. It''s the look in the eyes. Not crazy about the gold circle, but definitely imaginative.', '2007-10-22 22:06:47.000000', NULL, 1),
(4188574, 602868, 73452, '<td valign="top">I suspect a ribbon!  LOVE the leaves carpeting the ground.  Overall my favorite in the challenge, and a add to FAVS.  GREAT JOB!</td>', 'I suspect a ribbon!  LOVE the leaves carpeting the ground.  Overall my favorite in the challenge, and a add to FAVS.  GREAT JOB!', '2007-10-22 22:22:14.000000', NULL, 1),
(4188596, 603233, 83577, '<td valign="top">great idea</td>', 'great idea', '2007-10-22 22:30:33.000000', NULL, 1),
(4188625, 603046, 12311, '<td valign="top">Not bad.  With advanced editing, you could have removed the white spots.  Also, contrast can be improved on the box.  Nice effort.</td>', 'Not bad.  With advanced editing, you could have removed the white spots.  Also, contrast can be improved on the box.  Nice effort.', '2007-10-22 22:46:36.000000', NULL, 1),
(4188626, 603031, 12311, '<td valign="top">Ahh, the ubiquitous Falls rainbow!  Nice job.</td>', 'Ahh, the ubiquitous Falls rainbow!  Nice job.', '2007-10-22 22:47:37.000000', NULL, 1),
(4188687, 602868, 84124, '<td valign="top">Well done!  Nice idea on the theme of this challenge.</td>', 'Well done!  Nice idea on the theme of this challenge.', '2007-10-22 23:22:41.000000', NULL, 1),
(4188689, 601795, 84124, '<td valign="top">extraordinary!</td>', 'extraordinary!', '2007-10-22 23:23:56.000000', NULL, 1),
(4188691, 602428, 84124, '<td valign="top">Groovy!</td>', 'Groovy!', '2007-10-22 23:25:12.000000', NULL, 1),
(4188699, 603083, 84124, '<td valign="top">My highest vote in this challenge, fantastic!  Very creative, great take on the challenge theme.</td>', 'My highest vote in this challenge, fantastic!  Very creative, great take on the challenge theme.', '2007-10-22 23:29:28.000000', NULL, 1),
(4188731, 603233, 56275, '<td valign="top">Nice concept. Would have liked to seen the fabric ironed, or reflected on a different surface.</td>', 'Nice concept. Would have liked to seen the fabric ironed, or reflected on a different surface.', '2007-10-22 23:47:48.000000', NULL, 1),
(4188736, 603225, 56275, '<td valign="top">Great shot! I love their expressions and posture. A good mix of characters. Lighting and composition well executed. 10</td>', 'Great shot! I love their expressions and posture. A good mix of characters. Lighting and composition well executed. 10', '2007-10-22 23:49:59.000000', NULL, 1),
