(4190649, 602006, 67152, '<td valign="top">Excellent balance in this image - the lily pads so perfectly mirror and support the canoe.  The colors are so warm and vibrant and the ''aurora'' created by the reflection of the fall colors is such a refreshing rainbow</td>', 'Excellent balance in this image - the lily pads so perfectly mirror and support the canoe.  The colors are so warm and vibrant and the ''aurora'' created by the reflection of the fall colors is such a refreshing rainbow', '2007-10-23 22:56:46.000000', NULL, 1),
(4190655, 602034, 67152, '<td valign="top">nice spectral rainbows - the composition is pretty interesting but it seems that there isn''t quite enough contrast in the image - the blacks don''t quite seem black</td>', 'nice spectral rainbows - the composition is pretty interesting but it seems that there isn''t quite enough contrast in the image - the blacks don''t quite seem black', '2007-10-23 23:00:10.000000', NULL, 1),
(4190666, 603083, 67152, '<td valign="top">The b/w conversion with color is so incredibly well done - The lightness of the skin and and darkness of the lashes really help this one jump off the page.  You have done an excellent job of using diagonals to focus our attention and create life in the image.</td>', 'The b/w conversion with color is so incredibly well done - The lightness of the skin and and darkness of the lashes really help this one jump off the page.  You have done an excellent job of using diagonals to focus our attention and create life in the image.', '2007-10-23 23:04:48.000000', NULL, 1),
(4190671, 603238, 67152, '<td valign="top">that is one amazing rainbow - too bad that the trees seems to consume our view of this spectacular view</td>', 'that is one amazing rainbow - too bad that the trees seems to consume our view of this spectacular view', '2007-10-23 23:06:20.000000', NULL, 1),
(4190676, 603150, 67152, '<td valign="top">really good use of diagonals to create interest in the shot, both from the jacks and the grain of the wood</td>', 'really good use of diagonals to create interest in the shot, both from the jacks and the grain of the wood', '2007-10-23 23:08:27.000000', NULL, 1),
